//! The embedded, asset-free status page.

/// One page served at `/` with same-origin API requests only.
pub(crate) const HTML: &str = r#"<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>toolu · Epic status</title>
<style>
:root{font-family:ui-sans-serif,system-ui,sans-serif;color:#e7efec;background:#0d1518}*{box-sizing:border-box}body{margin:0;min-width:320px}::selection{background:#b8ebc4;color:#102019}button{font:inherit;cursor:pointer}button:focus-visible{outline:2px solid #b8ebc4;outline-offset:3px}
.shell{max-width:1480px;margin:auto;padding:0 32px 60px}.top{height:72px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #35464a}.brand{font-size:22px;letter-spacing:-.03em;font-weight:700}.brand span{color:#a9bfba;font-size:13px;font-weight:400;letter-spacing:0;margin-left:12px}.connection{font-size:13px;color:#bed0ca;display:flex;align-items:center;gap:9px}.dot{height:8px;width:8px;border-radius:50%;background:#a7e6b4;box-shadow:0 0 0 4px #a7e6b422}.off .dot{background:#efa983;box-shadow:0 0 0 4px #efa98322}
.intro{display:flex;justify-content:space-between;align-items:end;gap:20px;padding:36px 0 28px}.intro h1{font-size:clamp(32px,3.5vw,48px);letter-spacing:-.035em;line-height:1.1;margin:0}.intro p{color:#adbfba;margin:9px 0 0;font-size:14px}.updated{color:#a1b8b4;font-size:12px;white-space:nowrap;font-variant-numeric:tabular-nums}
.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-block:1px solid #35464a;margin:0 0 36px}.metric{padding:20px 22px 20px 0}.metric+.metric{border-left:1px solid #35464a;padding-left:22px}.metric dt{color:#a8bcb7;font-size:12px}.metric dd{font-size:28px;letter-spacing:-.03em;font-variant-numeric:tabular-nums;font-weight:650;margin:7px 0 0}.metric:last-child dd{color:#e8b58f}
.grid{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(280px,1fr);gap:34px}.stack{display:grid;gap:30px;align-content:start}.section{min-width:0}.section header{display:flex;align-items:baseline;justify-content:space-between;gap:10px;border-bottom:1px solid #35464a;padding-bottom:13px;margin-bottom:16px}.section h2{font-size:18px;letter-spacing:-.02em;margin:0}.section header span{font-size:12px;color:#9eb5b0}
.tabs{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:16px}.tab{border:1px solid #48605e;background:transparent;color:#d5e3dc;border-radius:7px;padding:7px 11px}.tab:hover{border-color:#a7d0b6}.tab[aria-selected=true]{border-color:#b8ebc4;background:#b8ebc4;color:#14291d;font-weight:650}
.board{background:#152025;border:1px solid #35474b;border-radius:11px;overflow:hidden}.board-head{padding:17px 19px;display:flex;justify-content:space-between;background:#1a292d;font-size:14px}.wave{padding:18px 19px;border-top:1px solid #35474b}.wave h3{color:#a9c7bb;font-size:12px;letter-spacing:.08em;text-transform:uppercase;margin:0 0 11px}.issue{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;align-items:center;border-top:1px solid #304146;padding:11px 0}.issue:first-of-type{border:0;padding-top:0}.issue strong{color:#b8ebc4;font-size:13px}.issue .title{display:block;font-size:14px;margin-top:3px}.issue small{color:#9fb4ae;display:block;margin-top:4px}.phase{font-size:12px;color:#d3e8d9;background:#30443c;padding:4px 7px;border-radius:5px;white-space:nowrap}.phase.failed,.phase.blocked{color:#ffd3b7;background:#57372e}.phase.execution,.phase.babysit{color:#cbe4fa;background:#2d4658}
.rows{border-top:1px solid #35474b}.row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:12px 0;border-bottom:1px solid #2c3d41;font-size:14px}.row small{display:block;color:#9eb5b0;font-size:12px;margin-top:4px}.value{font-variant-numeric:tabular-nums;white-space:nowrap}.warn{color:#edb18c}.list{list-style:none;padding:0;margin:0}.list li{padding:11px 0;border-bottom:1px solid #2c3d41;font-size:13px}.list small{display:block;color:#9eb5b0;margin-top:4px}.repo{color:#a8c4b8;font-size:12px;margin:16px 0 5px}.empty{padding:22px 19px;color:#aabfba;font-size:14px;line-height:1.5}.error{padding:14px 17px;background:#4b302b;color:#ffcfb4;border-radius:8px;margin-bottom:20px;font-size:14px}.footer{border-top:1px solid #35464a;margin-top:50px;padding-top:17px;color:#9db3ae;font-size:12px}.machines{margin:0 0 22px}.tab small{display:block;font-size:11px;font-weight:400;opacity:.85;margin-top:2px}.notice{padding:14px 17px;background:#2d3d40;color:#e7efec;border-radius:8px;margin-bottom:20px;font-size:14px}
@media(max-width:900px){.grid{grid-template-columns:1fr}.stack{grid-template-columns:repeat(2,minmax(0,1fr))}.summary{grid-template-columns:repeat(2,minmax(0,1fr))}.metric:nth-child(3){border-left:0;padding-left:0;border-top:1px solid #35464a}.metric:nth-child(4){border-top:1px solid #35464a}}
@media(max-width:620px){.shell{padding:0 18px 40px}.brand span{display:none}.intro{display:block}.updated{display:block;margin-top:15px}.stack{display:block}.stack .section{margin-bottom:30px}.metric{padding:15px 10px 15px 0}.metric+.metric{padding-left:10px}.metric:nth-child(3){padding-left:0}.metric dd{font-size:24px}}
</style></head><body><div class="shell">
<header class="top"><div class="brand">toolu <span>Epic operations</span></div><div id="connection" class="connection off"><span class="dot" aria-hidden="true"></span><span id="connection-text">Connecting</span></div></header>
<main><dl id="fleet-summary" class="summary" hidden><div class="metric"><dt>Machines reachable</dt><dd id="fleet-machines">—</dd></div><div class="metric"><dt>Hosts busy</dt><dd id="fleet-hosts">—</dd></div><div class="metric"><dt>In flight</dt><dd id="fleet-inflight">—</dd></div><div class="metric"><dt>Needs attention</dt><dd id="fleet-attention">—</dd></div></dl><div id="machines" class="tabs machines" role="tablist" aria-label="Machines" hidden></div><div class="intro"><div><h1 id="title">Epic status</h1><p>Workers, hosts, and shared capacity across registered epics.</p></div><time id="updated" class="updated">Waiting for engine</time></div><div id="error" class="error" role="alert" hidden></div><div id="machine-state" class="notice" role="status" hidden></div>
<div id="panels"><dl class="summary"><div class="metric"><dt>Registered epics</dt><dd id="metric-epics">—</dd></div><div class="metric"><dt>Active workers</dt><dd id="metric-workers">—</dd></div><div class="metric"><dt>Running jobs</dt><dd id="metric-jobs">—</dd></div><div class="metric"><dt>Needs attention</dt><dd id="metric-attention">—</dd></div></dl>
<div class="grid"><section class="section"><header><h2>Epic boards</h2><span id="epic-count"></span></header><div id="tabs" class="tabs" role="tablist" aria-label="Epics"></div><div id="board" class="board"><div class="empty">Loading registered epics…</div></div></section><div class="stack">
<section class="section"><header><h2>Hosts</h2><span>Agent slots</span></header><div id="hosts" class="rows"></div></section><section class="section"><header><h2>Machine</h2><span>Shared resources</span></header><div id="machine" class="rows"></div></section><section class="section"><header><h2>Jobs</h2><span>Running and waiting</span></header><ul id="jobs" class="list"></ul></section><section class="section"><header><h2>Merge queue</h2><span>Ready by repository</span></header><div id="queue"></div></section><section class="section"><header><h2>Attention</h2><span id="attention-count"></span></header><ul id="attention" class="list"></ul></section>
</div></div></div></main><footer class="footer">Read-only local status · Live journal updates</footer></div>
<script>
const $=id=>document.getElementById(id),state={epics:[],selected:null,details:new Map(),machine:null,fleet:null,solo:false,generation:0,busy:false};
const base=()=>state.machine===null?'/api/v1':`/api/v1/fleet/peers/${encodeURIComponent(state.machine)}`;
const current=()=>state.machine===null?null:(state.fleet?.machines||[]).find(m=>!m.local&&m.name===state.machine)||null;
const fmt=n=>Number.isFinite(n)?new Intl.NumberFormat().format(n):'—';
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=String(text);return e;};
const clear=(id,text)=>$(id).replaceChildren(el('div','empty',text));
async function get(path){const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw Error(`${path}: HTTP ${r.status}`);return r.json();}
function row(target,title,value,detail,warn){const r=el('div','row'),l=el('div');l.append(el('strong','',title));if(detail)l.append(el('small','',detail));r.append(l,el('span',warn?'value warn':'value',value));target.append(r);}
function tabs(){const t=$('tabs');t.replaceChildren();$('epic-count').textContent=`${state.epics.length} registered`;for(const epic of state.epics){const b=el('button','tab',epic.key);b.type='button';b.role='tab';b.setAttribute('aria-selected',String(epic.key===state.selected));b.onclick=()=>select(epic.key);t.append(b);}}
function board(){const b=$('board');b.replaceChildren();const d=state.details.get(state.selected);if(!d){clear('board','No registered epics yet. Start one with toolu epic start.');return;}const h=el('div','board-head');h.append(el('strong','',d.key),el('span','',d.paused?'Paused':'Active'));b.append(h);const issues=new Map((d.issues||[]).map(i=>[i.key,i])),nodes=new Map((d.graph?.issues||[]).map(i=>[i.key,i]));if(!d.graph?.waves?.length){b.append(el('div','empty','No issues in this epic yet.'));return;}for(const wave of d.graph.waves){const g=el('section','wave');g.append(el('h3','',`Wave ${wave.wave}`));for(const key of wave.issues||[]){const i=issues.get(key)||{},m=nodes.get(key)||{},line=el('div','issue'),label=el('div');label.append(el('strong','',key),el('span','title',m.title||'Untitled issue'));if(m.open_blockers?.length)label.append(el('small','',`Blocked by ${m.open_blockers.join(', ')}`));line.append(label,el('span',`phase ${i.phase||''}`,i.phase||i.stage||'Pending'));g.append(line);}b.append(g);}}
function listItem(target,title,detail){const li=el('li');li.append(el('strong','',title));if(detail)li.append(el('small','',detail));target.append(li);}
function render(o,e,h,m,j,q,a){state.epics=e.items||[];if(!state.epics.some(x=>x.key===state.selected))state.selected=state.epics[0]?.key||null;$('metric-epics').textContent=fmt(state.epics.length);$('metric-workers').textContent=fmt(o.counts?.running||0);$('metric-jobs').textContent=fmt(j.running?.length||0);$('metric-attention').textContent=fmt(a.items?.length||0);tabs();board();
const hosts=$('hosts');hosts.replaceChildren();for(const x of h.items||[])row(hosts,x.host,`${x.running} / ${x.cap}`,x.cooldown_until?`Cooldown until ${new Date(x.cooldown_until).toLocaleTimeString()} · ${x.reason||''}`:'Available',!!x.cooldown_until);if(!hosts.children.length)clear('hosts','No host capacity reported.');
const machine=$('machine');machine.replaceChildren();row(machine,'Load',fmt(m.load),m.pressure?.held?`Capacity hold: ${m.pressure.reason||'pressure'}`:'Current system load',m.pressure?.held);row(machine,'Available memory',m.available_memory_bytes==null?'—':`${(m.available_memory_bytes/1073741824).toFixed(1)} GiB`);row(machine,'Agent leases',fmt(m.agent_leases?.length||0));row(machine,'Job slots',`${m.job_leases?.length||0} / ${m.policy?.max_jobs??'—'}`);
const jobs=$('jobs');jobs.replaceChildren();for(const x of j.running||[])listItem(jobs,`Running · ${x.owner||'job'}`,x.worktree);for(const x of j.waiting||[])listItem(jobs,`Waiting · ${x.key||'job'}`,x.worktree);if(!jobs.children.length)listItem(jobs,'No expensive jobs running or waiting.');
const queue=$('queue');queue.replaceChildren();for(const r of q.repositories||[]){queue.append(el('div','repo',r.repo));const ul=el('ul','list');for(const x of r.items||[])listItem(ul,`${x.position}. ${x.key}`);queue.append(ul);}if(!queue.children.length)clear('queue','No issues ready for the merge queue.');
const attention=$('attention');attention.replaceChildren();$('attention-count').textContent=`${a.items?.length||0} live`;for(const x of a.items||[])listItem(attention,`${x.key} · ${x.kind} · ${x.state}`,x.note);if(!attention.children.length)listItem(attention,'Nothing needs attention.');}
async function select(key){state.selected=key;try{if(!state.details.has(key))state.details.set(key,await get(`${base()}/epics/${encodeURIComponent(key)}`));tabs();board();}catch(err){showError(err);}}
function showError(err){$('error').hidden=false;$('error').textContent=`Status unavailable: ${err.message}. The page will retry on the next engine update.`;}
async function docs(paths){if(state.machine===null)return Promise.all(paths.map(get));const out=[];for(const p of paths)out.push(await get(p));return out;}
function banner(m){if(m.state==='ok')return 'Live';if(m.state==='unreachable')return m.last_seen?`Unreachable · last seen ${new Date(m.last_seen).toLocaleString()}`:'Unreachable · never seen';if(m.state==='unauthorized')return m.reason==='token'?'Unauthorized: token rejected':m.reason==='host'?'Unauthorized: host rejected':'Unauthorized';return 'Version mismatch';}
function machineTabs(f){const ms=f.machines||[],multi=ms.length>1;$('fleet-summary').hidden=!multi;$('machines').hidden=!multi;if(!multi)return;const s=f.summary||{},hosts=s.hosts||[];$('fleet-machines').textContent=`${fmt(s.reachable)} / ${fmt(s.machines)}`;$('fleet-hosts').textContent=`${fmt(hosts.reduce((n,h)=>n+(h.running||0),0))} / ${fmt(hosts.reduce((n,h)=>n+(h.cap||0),0))}`;$('fleet-inflight').textContent=fmt(s.in_flight);$('fleet-attention').textContent=fmt(s.attention_count);const t=$('machines');t.replaceChildren();for(const m of ms){const key=m.local?null:m.name,b=el('button','tab',m.local?'This machine':m.name);b.type='button';b.role='tab';b.setAttribute('aria-selected',String(key===state.machine));b.append(el('small','',m.local?'Live':banner(m)));b.onclick=()=>pick(key);t.append(b);}}
async function fleet(){try{state.fleet=await get('/api/v1/fleet');state.solo=(state.fleet.machines||[]).length<2;if(state.machine!==null&&!current())state.machine=null;machineTabs(state.fleet);}catch(err){showError(err);}}
function pick(key){state.machine=key;state.selected=null;state.details.clear();if(state.fleet)machineTabs(state.fleet);refresh();}
async function refresh(){const m=current();$('title').textContent=m?`Epic status · ${m.name}`:'Epic status';const generation=++state.generation;if(m&&m.state!=='ok'){$('panels').hidden=true;$('error').hidden=true;$('machine-state').hidden=false;$('machine-state').textContent=`${m.name}: ${banner(m)}`;return;}$('panels').hidden=false;$('machine-state').hidden=true;state.busy=true;try{const b=base(),list=await docs(['overview','epics','hosts','machine','jobs','queue','attention'].map(x=>`${b}/${x}`));const epics=list[1].items||[];if(!epics.some(x=>x.key===state.selected))state.selected=epics[0]?.key||null;const detail=state.selected?await get(`${b}/epics/${encodeURIComponent(state.selected)}`):null;if(generation!==state.generation)return;state.details.clear();if(state.selected)state.details.set(state.selected,detail);render(...list);$('error').hidden=true;$('updated').textContent=`Updated ${new Date().toLocaleTimeString()}`;}catch(err){if(generation===state.generation)showError(err);}finally{if(generation===state.generation)state.busy=false;}}
let scheduled=false;function schedule(){if(scheduled)return;scheduled=true;setTimeout(()=>{scheduled=false;if(!state.solo)fleet();if(state.machine===null)refresh();},100);}
setInterval(()=>{if(state.solo)return;fleet().then(()=>{if(state.machine!==null&&!state.busy)refresh();});},5000);
const events=new EventSource('/api/v1/events/stream');events.addEventListener('open',()=>{$('connection').classList.remove('off');$('connection-text').textContent='Live';});events.addEventListener('journal',schedule);events.addEventListener('reset',schedule);events.onerror=()=>{$('connection').classList.add('off');$('connection-text').textContent='Reconnecting';};refresh();fleet();
</script></body></html>"#;

#[cfg(test)]
#[path = "tests/dashboard_test.rs"]
mod tests;
